/* ===== colourful profile: hero, coloured card bands, readable type, compact form, long-text safety ===== */
.pc-blue{--th:#397ef6;--th2:#2a5fd0;--th-soft:#e8f0ff}.pc-indigo{--th:#5b5ce6;--th2:#3f3fc2;--th-soft:#ececff}.pc-amber{--th:#eab308;--th2:#b9840a;--th-soft:#fff7d9}
.pc-purple{--th:#9b6cf5;--th2:#6d45d6;--th-soft:#f2ecff}.pc-green{--th:#22b26b;--th2:#138a50;--th-soft:#e4f7ec}.pc-rose{--th:#ec4f7f;--th2:#c9305f;--th-soft:#ffe9f0}
.pc-orange{--th:#f58a2c;--th2:#d9601c;--th-soft:#fff1e3}.pc-teal{--th:#14b3a3;--th2:#0b8577;--th-soft:#e2f7f4}.pc-slate{--th:#64748b;--th2:#475569;--th-soft:#eef2f6}
.hero{background:linear-gradient(125deg,#13295a,#397ef6 60%,#7257df)}
.hero:after{background:linear-gradient(90deg,rgba(13,31,62,.55),rgba(57,126,246,.05))}
.hero:before{content:"";position:absolute;z-index:1;right:-80px;top:-100px;width:280px;height:280px;border-radius:50%;background:rgba(255,255,255,.1)}
.hero .logo{box-shadow:0 12px 28px rgba(0,0,0,.25)}
.hero h1,.contact-owner-copy strong,.offering h3,.review-author{overflow-wrap:anywhere}
.category{font-size:12px;padding:6px 11px;background:rgba(255,255,255,.18);border:1px solid rgba(255,255,255,.25)}
.card.pcard{padding:0;border:0;border-radius:22px;overflow:hidden;background:linear-gradient(135deg,color-mix(in srgb,var(--th2) 70%,#0b1a3a),var(--th2));box-shadow:0 14px 30px color-mix(in srgb,var(--th2) 20%,transparent)}
.pc-band{padding:18px 22px 38px;color:#fff}
.pc-band h2,.card.pcard .pc-band h2{margin:0;color:#fff;font-size:20px;line-height:1.3;overflow-wrap:anywhere}
.pc-band>p,.lead-card .pc-band>p{margin:5px 0 0;color:rgba(255,255,255,.85);font-size:14px;line-height:1.5}
.pc-band .owner-about-label{background:rgba(255,255,255,.2);color:#fff;font-size:12px}
.pc-body{position:relative;margin-top:-22px;padding:22px;border-radius:20px 20px 0 0;background:#fff;min-width:0}
.pc-body .about{font-size:15px;line-height:1.7;color:#33435c;overflow-wrap:anywhere}
.pcard .btn.primary{border:0;border-radius:999px;background:linear-gradient(135deg,var(--th),var(--th2));box-shadow:0 8px 18px color-mix(in srgb,var(--th) 30%,transparent)}
.pcard .input:focus{border-color:var(--th);box-shadow:0 0 0 3px color-mix(in srgb,var(--th) 20%,transparent)}
/* readable type (was 9-11px) */
.field label{font-size:13px;color:#33435c}
.input{font-size:15px}
.error{font-size:12px}.notice{font-size:13px}
.review-count{font-size:12px}.review-author{font-size:14px}.review-date{font-size:12px}.review .stars{font-size:13px}.review p{font-size:13px}
.detail span{font-size:12px}.media-caption{font-size:13px}.offering p{font-size:13px}.price{font-size:13px}.offering h3{font-size:15px}
.contact-owner{background:var(--th-soft)}
.contact-owner-copy small{font-size:11px;color:var(--th2)}
.contact-owner-copy span{font-size:13px;white-space:normal;overflow-wrap:anywhere}
.contact-owner-copy strong{white-space:normal}
.contact-fact{font-size:13px;min-width:0;max-width:100%}
.contact-fact b{font-size:11px;color:var(--th2)}
.contact-fact span{min-width:0;overflow-wrap:anywhere;word-break:break-word}
.contact-social .btn{font-size:13px;min-height:38px;border-radius:999px}
.owner-about-label{font-size:12px}
/* compact enquiry form */
.lead-card .field{margin-bottom:10px}
.lead-card .field label{margin-bottom:4px}
.lead-card .input{min-height:42px;padding:9px 12px;border-radius:10px}
.lead-card textarea.input{min-height:86px;resize:vertical}
.lead-card .grid2{gap:10px}
.lead-card .grid2>.field{min-width:0}
.form-note{margin:-2px 0 10px;color:#6b7890;font-size:12px}
.send-btn{width:100%;min-height:46px;font-size:15px}
@media(max-width:767.98px){.pc-band{padding:16px 18px 36px}.pc-band h2,.card.pcard .pc-band h2{font-size:18px}.pc-body{padding:18px}.input{font-size:16px}.card.pcard{border-radius:20px}}
@media(max-width:520px){.lead-card .grid2{grid-template-columns:1fr 1fr}.card.pcard.contact-card{padding:0}}
@media(max-width:360px){.lead-card .grid2{grid-template-columns:1fr}}

/* QR card + remaining small labels */
.card.qr-card.pcard{display:block;padding:0;max-width:none}
.qr-body{display:flex;align-items:center;gap:16px}
.qr-body .qr-copy .btn{min-height:42px;padding:0 18px;border-radius:999px;border:0;background:var(--th-soft);color:var(--th2);font-size:14px;font-weight:700}
.hero .eyebrow{font-size:12px!important}
.hero .category{font-size:12px!important}
.contact-owner-copy small,.contact-fact b{font-size:12px!important}

/* never let long names/emails widen the layout */
.layout>*,.layout aside,.pcard,.pc-band,.pc-body{min-width:0}
.pc-band,.pc-band *,.pc-body p,.pc-body h3,.contact-owner-copy *{overflow-wrap:anywhere}
@media(max-width:800px){.layout{grid-template-columns:minmax(0,1fr)}}

.owner-initials{display:grid;place-items:center;width:62px;height:62px;flex:0 0 62px;border:3px solid #fff;border-radius:16px;background:linear-gradient(135deg,var(--th),var(--th2));color:#fff;font-size:20px;font-weight:800;box-shadow:0 5px 15px #254b8130}
.owner-initials[hidden],.contact-owner-photo[hidden]{display:none}
/* product enquiry pop-up: coloured header, compact fields */
.themed-dialog{overflow:hidden;border-radius:22px!important;background:linear-gradient(135deg,color-mix(in srgb,var(--th2) 70%,#0b1a3a),var(--th2))!important}
.themed-dialog form{background:transparent}
.themed-dialog .dialog-head{padding:18px 20px 38px;border:0;color:#fff}
.themed-dialog .dialog-head h2{color:#fff;font-size:18px;overflow-wrap:anywhere}
.themed-dialog .dialog-close{border-radius:999px;background:rgba(255,255,255,.18);border:1px solid rgba(255,255,255,.3);color:#fff}
.themed-dialog .dialog-body{position:relative;margin-top:-22px;border-radius:20px 20px 0 0;background:#fff;padding:20px}
.themed-dialog .dialog-body .field{margin-bottom:10px}
.themed-dialog .dialog-body textarea.input{min-height:86px}
.themed-dialog .dialog-foot{background:#fff;border-top:1px solid #eef1f6}
.themed-dialog .dialog-foot .btn{flex:1;min-height:44px;border-radius:999px}
.themed-dialog .dialog-foot .btn.primary{border:0;background:linear-gradient(135deg,var(--th),var(--th2))}
.themed-dialog .dialog-foot .btn:not(.primary){border:0;background:var(--th-soft);color:var(--th2)}
.themed-dialog .input:focus{border-color:var(--th);box-shadow:0 0 0 3px color-mix(in srgb,var(--th) 20%,transparent)}

.whatsapp-float{display:inline-flex;align-items:center;gap:8px}
.wa-icon{width:22px;height:22px;fill:#fff;flex:0 0 22px}
@media(max-width:800px){.whatsapp-float{width:54px;height:54px;padding:0;justify-content:center;right:14px;bottom:14px}.whatsapp-float .wa-text{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}.wa-icon{width:28px;height:28px;flex-basis:28px}.layout{padding-bottom:70px}}

/* show whole product image at every width */
.offering img{height:auto;aspect-ratio:4/3;object-fit:contain;background:#f5f7fb}
</style>
